contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive sequence: set an initial MinSum, mark initialized, then attempt SetMinSum again.
    // Parameters:
    // initial := initial value to set before Initialized
    // newval := value to attempt to set after Initialized
    function check(uint initial, uint newval) public {
        // set initial MinSum (first call before Initialized)
        c.SetMinSum(initial);
        // mark initialized so original contract will prevent further changes
        c.Initialized();
        // attempt to change MinSum after initialization
        c.SetMinSum(newval);
        // observe MinSum via public getter and assert it didn't change
        uint observed = c.MinSum();
        assert(observed == initial);
    }

    // accept ether in case underlying calls require msg.value from this contract in other tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) {
        c = _c;
    }

    // Drive the contract and assert the distinguishing property
    // Parameters:
    //  - min: value to pass to SetMinSum
    // We need only call Initialized() first, then attempt SetMinSum(min).
    // On P this should revert (because nonReentrant_ locks and SetMinSum checks intitalized and reverts if already true),
    // while on M the no-op modifier allows SetMinSum to run and succeed, breaking the rule.
    function run(uint min) public {
        // make the contract reach initialized state
        c.Initialized();

        // Attempt SetMinSum; capture whether it reverts.
        bool didRevert = false;
        // low-level call to detect revert without bubbling
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", min));
        didRevert = !ok;

        // The distinguishing assertion: after Initialized(), SetMinSum must revert
        assert(didRevert);
    }

    // allow receiving ETH just in case
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: addr is implicit msg.sender of this contract; amount funds sent to c via Put; collectAmt is passed to Collect
    function run(uint putLock, uint amount, uint collectAmt) public payable {
        require(address(this).balance >= amount, "insufficient balance to fund Put");
        // deposit into c so this contract becomes a holder with balance >= MinSum condition can be arranged by caller
        c.Put{value: amount}(putLock);
        // read MinSum before Collect
        uint before = c.MinSum();
        // perform the state-changing call whose behavior differs between Original and Mutant
        c.Collect(collectAmt);
        // read MinSum after Collect
        uint after = c.MinSum();
        // general property: Collect should not change MinSum
        assert(after == before);
    }
    receive() external payable { }
}

