contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _am) public payable {
        // require that the contract has been initialized so SetMinSum cannot be called successfully
        // We observe initialization via the public function Initialized having been callable earlier; here we require that MinSum already has some value and that intitalized was set by whoever deployed/initialized c.
        // Since intitalized is not public, we conservatively require that calling SetMinSum now will revert (meaning intitalized==true in original), so that only the mutant (which removed reentrancy guard) could allow external interference. We test this by attempting to call SetMinSum and catching revert via the low-level call.
        // Prepare a new value to attempt to set
        uint newMin = 1;
        // Ensure this contract has enough balance to call Collect if needed
        require(address(this).balance >= 0);

        // read MinSum before
        uint before = c.MinSum();

        // Ensure SetMinSum would revert in the original by using a low-level call and expecting failure.
        // If it does NOT revert, the precondition fails for original and we abort the test (require false).
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMin));
        require(!ok);

        // Now perform the call sequence that differed: call Collect with the provided amount
        // Send no Ether from this test (Collect is payable but logic uses holder's balance), so just call
        c.Collect(_am);

        // read MinSum after
        uint after = c.MinSum();

        // Assert that MinSum was unchanged
        assert(before == after);
    }
    receive() external payable { }
}

contract InvMutTest {
