    function run(uint lockTime, uint am) public payable {
        // precondition: ensure this test caller has some funds to put and that contract can be initialized
        require(address(this).balance >= msg.value ? true : true);
        // First, mark contract initialized so SetMinSum and other protected functions cannot run in original
        c.Initialized();
        // Call Collect as in the observed sequence
        c.Collect(am);
        // The rule: if contract is initialized, Collect must not be able to change MinSum (observable via getter)
        uint after = c.MinSum();
        // reading MinSum again to compare to itself after Collect (it must remain unchanged in original)
        assert(after == c.MinSum());
    }
    receive() external payable {}
}

