pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: sender address and amount to collect/put and lockTime
    function testFuzz_property(address sender, uint96 putAmount, uint32 lockTime, uint96 collectAmount) public {
        // keep domains wide but sensible
        vm.assume(sender != address(0));
        // ensure some ETH for sender
        uint256 putVal = uint256(putAmount) + 1; // avoid zero
        vm.deal(sender, putVal + 1 ether);

        // initialize contract with MinSum > 0 under the nonReentrant guard
        // call SetMinSum via an externally owned account (use sender)
        vm.prank(sender);
        c.SetMinSum(1);

        // ensure the log file is set to an innocuous address (self) to avoid external effects
        vm.prank(sender);
        c.SetLogFile(address(this));

        // mark initialized so SetMinSum/SetLogFile cannot be called later
        vm.prank(sender);
        c.Initialized();

        // record MinSum before
        uint256 before = c.MinSum();

        // make a Put from sender to create a balance
        vm.prank(sender);
        c.Put{value: putVal}(lockTime);

        // attempt to Collect; wrap in try/catch to tolerate revert differences
        bool ok;
        vm.prank(sender);
        try c.Collect(uint256(collectAmount)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: reference contract never changes MinSum during Collect, so MinSum remains equal to before.
        // This single assertion must hold for the reference for all inputs and will fail for the mutant that disables the lock
        assertTrue(c.MinSum() == before);
    }
}

