pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: attacker initial deposit, collect amount, lockTime, and an initial MinSum value
    function testFuzz_property(uint96 deposit, uint96 collectAmt, uint32 lockTime, uint96 initialMinSum) public {
        // keep values in reasonable ranges but still wide
        uint256 dep = uint256(deposit);
        uint256 amt = uint256(collectAmt);
        uint256 lockT = uint256(lockTime);
        uint256 minS = uint256(initialMinSum);

        // ensure non-zero deposit to interact
        vm.assume(dep > 0);
        // allow collect amount to be within full uint range but not absurdly larger than deposit
        // (we still allow amt > dep; Collect will check balance >= _am)

        // Deploy attacker helper that will re-enter Collect and attempt to call SetMinSum during reentrancy
        Attacker attacker = new Attacker(address(c));

        // fund attacker and the contract as needed
        vm.deal(address(attacker), dep + 1 ether);

        // Initialize C: set MinSum and set LogFile to a benign address (use attacker as log to enable reentry)
        // Set LogFile and MinSum must be called before Initialized is set to true. Both are nonReentrant_ in reference.
        // We use attacker as Log so that during Collect the Log.AddMessage will execute on attacker, enabling reentry.
        c.SetLogFile(address(attacker));
        c.SetMinSum(minS);
        // mark initialized so further Set* cannot be called
        c.Initialized();

        // Attacker will receive messages via AddMessage call (LogFile.AddMessage) and re-enter Collect
        // Make sure attacker has deposited funds into C by calling Put via attacker fallback
        // attacker will call c.Put{value: dep}(lockT)
        attacker.fundAndPut{value: dep}(address(c), dep, lockT);

        // record MinSum before calling Collect
        uint256 before = c.MinSum();

        // Now attempt Collect from attacker: during Collect, LogFile.AddMessage triggers attacker.receive which re-enters
        // The attacker will during reentry try to call SetMinSum to change MinSum. In the reference this should fail
        // because nonReentrant_ prevents reentry into functions using the modifier (including SetMinSum). In the mutant,
        // modifier is no-op and SetMinSum can succeed during reentry, changing MinSum.

        // Call Collect from attacker with amt; use vm.prank to set msg.sender
        vm.prank(address(attacker));
        // Make sure attacker has enough balance in contract for Collect to proceed; attacker deposited dep
        // If amt > dep Collect will not execute transfer; still we allow fuzz to choose amt but assume at least 1
        vm.assume(amt > 0);

        bool ok;
        try c.Collect(uint256(amt)) {
            ok = true;
        } catch {
            ok = false;
        }

        // After Collect completes, the reference C guarantees MinSum is unchanged for every admissible input.
        // The buggy mutant (without reentrancy guard) can have MinSum changed by reentrant SetMinSum.
        assertTrue(c.MinSum() == before);
    }
}

// Minimal adversarial helper that acts as Log and re-enters Collect when AddMessage is called
contract Attacker {
    address public target;
    bool public reentered;

    constructor(address _t) {
        target = _t;
        reentered = false;
    }

    // helper to fund attacker and call Put on target
    function fundAndPut(address caddr, uint256 value, uint256 lockTime) external payable {
        // called with value funded by vm.deal
        C(caddr).Put{value: value}(lockTime);
    }

    // This function matches Log.AddMessage(address,uint,string)
    // It's not the exact signature (string calldata) but solidity will allow matching by name/arg types when called via interface-less call.
    // To ensure we are invoked, define a fallback that decodes and calls AddMessage-targeting data if needed.

    // The contract will be called by C.LogFile.AddMessage, which is a normal call. We implement a function with that selector.
    function AddMessage(address _adr, uint _val, string memory _data) public {
        // During AddMessage, try to re-enter and call SetMinSum on the target to attempt to change it.
        if (!reentered) {
            reentered = true;
            // attempt to set MinSum to a new value (e.g., 1)
            // It will succeed only if target's nonReentrant_ is disabled
            try C(target).SetMinSum(1) {
            } catch {
            }
            reentered = false;
        }
    }

    // receive to accept ETH if needed
    receive() external payable {}
}

