pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: attacker deposit and withdraw amount, and a value to set MinSum reentrantly
    function testFuzz_property(uint256 deposit, uint256 withdraw, uint256 newMin) public {
        // keep values in reasonable ranges but wide enough
        deposit = bound(deposit, 1, 1 ether);
        withdraw = bound(withdraw, 1, deposit);
        newMin = bound(newMin, 0, 1 ether);

        // deploy attacker helper and fund it
        Attacker attacker = new Attacker(address(c));
        vm.deal(address(attacker), deposit + 0.1 ether);

        // Initialize contract: set MinSum to some baseline via owner (use attacker to call SetMinSum)
        // Contract has no access control in SetMinSum other than nonReentrant_, so anyone can call it.
        vm.prank(address(attacker));
        c.SetMinSum(1); // set baseline to nonzero

        // Set LogFile to attacker so Put and Collect will call into attacker's contract when logging
        vm.prank(address(attacker));
        c.SetLogFile(address(attacker));

        // Mark initialized to true so further SetMinSum would revert in normal flow if nonReentrant_ were active
        vm.prank(address(attacker));
        c.Initialized();

        // record MinSum before attack
        uint256 before = c.MinSum();

        // make attacker deposit via Put (call fallback by sending ether to c through attacker)
        // attacker will perform a Put with the value
        attacker.deposit{value: deposit}(withdraw, address(this));

        // Now trigger Collect from attacker which in the buggy contract can reenter and call SetMinSum
        // Attacker's fallback/reentrant code will attempt to call c.SetMinSum(newMin)
        attacker.triggerCollect(withdraw, newMin);

        // Single assertion: reference contract preserves MinSum for all inputs, buggy one will differ for some
        assertTrue(c.MinSum() == before);
    }
}

// Minimal attacker which will reenter during the LogFile.AddMessage call by being the LogFile
contract Attacker {
    C public target;
    address public tester;
    bool public reentered;

    constructor(address _t) payable {
        target = C(_t);
    }

    // helper to deposit via fallback: call Put by sending ether to target so fallback -> Put(0) executes
    function deposit(uint256 wantWithdraw, address _tester) external payable {
        tester = _tester;
        // call Put directly so LogFile.AddMessage will be invoked and route to this contract
        target.Put{value: msg.value}(0);
    }

    // trigger Collect from this attacker (prank not needed as this contract is the caller)
    function triggerCollect(uint256 _am, uint256 _newMin) external {
        // store desired newMin in a slot accessible to fallback
        reentered = false;
        // attempt to collect which will cause LogFile.AddMessage -> this contract fallback
        target.Collect{value: 0}(_am);
        // after Collect returns, nothing here
        // but during Collect (when target calls LogFile.AddMessage) fallback() will run and attempt reentry
        // fallback uses stored _newMin inside this call via reentrant call to SetMinSum
        // we pass newMin via a temporary mechanism: we call SetMinSum now if not already done
        // (this is just precaution; main reentry happens in fallback below)
        // no-op here
    }

    // The Log.AddMessage from target will call into this contract; use fallback to perform reentrant SetMinSum
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // attempt to reenter and change MinSum
            // ignore failures
            try target.SetMinSum(0) {
            } catch {
            }
        }
    }
}

