contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: attacker initial balance deposit, collect amount, and a value to set MinSum in reentrancy
    function testFuzz_property(uint256 deposit, uint256 collectAmt, uint256 newMin) public {
        // keep values in practical bounds
        deposit = bound(deposit, 1, 1 ether);
        collectAmt = bound(collectAmt, 0, deposit);
        newMin = bound(newMin, 0, 1 ether);

        // deploy an attacker that will re-enter Collect and call SetMinSum to change MinSum if reentrancy is possible
        Attacker attacker = new Attacker(address(c), newMin);

        // fund attacker
        vm.deal(address(attacker), deposit);

        // initialize c: set MinSum to a known value and set LogFile to attacker so callbacks go through attacker
        // need to call SetMinSum and SetLogFile before Initialized()
        // we call them from this test account
        c.SetMinSum(0);
        c.SetLogFile(address(attacker));
        // finalize initialization so attacker cannot call SetMinSum later except via reentrancy if possible
        c.Initialized();

        // Attacker will deposit into c by calling Put via its fallback (we instruct attacker to call Put by sending value)
        vm.prank(address(attacker));
        attacker.doDeposit{value: deposit}();

        // record MinSum before Collect
        uint256 before = c.MinSum();

        // Now trigger Collect from attacker so if reentrancy is possible, attacker will re-enter and call SetMinSum
        // Use try/catch to ensure we observe whether Collect succeeded or reverted
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: on the correct contract, MinSum must remain equal to before for ALL inputs.
        // If the mutant removed the reentrancy guard, attacker reentry can change MinSum to newMin, so this will fail for some inputs.
        assertTrue(c.MinSum() == before);
    }
}

// Attacker that, when called by C.LogFile.AddMessage (which is external), will attempt to re-enter Collect
contract Attacker {
    address immutable target;
    uint256 immutable toSet;

    constructor(address _t, uint256 _toSet) payable {
        target = _t;
        toSet = _toSet;
    }

    // helper to deposit into C by calling its fallback which routes to Put(0)
    function doDeposit() external payable {
        // call the fallback of C by sending value
        (bool s, ) = target.call{value: msg.value}("");
        require(s);
    }

    // This function has same signature as Log.AddMessage so C will call it when logging
    // During that external call from C, this contract will attempt to call SetMinSum on C (reentrancy)
    function AddMessage(address, uint, string memory) public {
        // re-enter to SetMinSum; if nonReentrant_ is active this will revert or be prevented
        C(target).SetMinSum(toSet);
    }

    // receive to accept ETH
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive c so that on the original contract SetMinSum cannot set MinSum when not initialized.
    // Parameters: val to attempt to set, and a flag to optionally initialize before the call.
    function run(uint _val, bool doInitialize) public {
        // ensure caller has some balance if needed by other calls (not needed here)
        // Optionally initialize the contract by calling Initialized(), which sets intitalized = true.
        if (doInitialize) {
            c.Initialized();
        }

        // Read MinSum before attempting to set
        uint before = c.MinSum();

        // Attempt to set MinSum (this is the statement mutated in M)
        c.SetMinSum(_val);

        // Read MinSum after the call
        uint after = c.MinSum();

        // General rule: if we did NOT initialize before calling SetMinSum, MinSum must remain equal to its previous value.
        // This holds on P because SetMinSum reverts when intitalized == false, leaving MinSum unchanged.
        // The mutant inverts the guard and would change MinSum even when not initialized, violating this assertion.
        if (!doInitialize) {
            assert(after == before);
        } else {
            // If we did initialize, no general rule about change is guaranteed; still assert it's a uint (trivial) by asserting non-negativity.
            assert(after >= 0);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We will simulate a caller that tries to Collect; the rule: if MinSum was set before initialization
    // and the contract is still not initialized, then a Collect call must NOT change MinSum.
    function run(address caller, uint sendAmount, uint collectAmount) public payable {
        require(address(this).balance >= sendAmount);
        // Preconditions: caller is some external account that already has a balance in c large enough
        // to attempt Collect. We cannot set Acc directly; instead rely on that Collect will be called
        // from this test contract (acting as caller). First, ensure MinSum has some nonzero value by calling SetMinSum via c.
        // Only call SetMinSum if the contract is not initialized; otherwise it would revert in original.
        // We check current MinSum and only call SetMinSum when it is zero to set to a nonzero sentinel.
        uint beforeMin = c.MinSum();
        if (beforeMin == 0) {
            // set MinSum to sendAmount (safe nonzero)
            c.SetMinSum(sendAmount);
            beforeMin = c.MinSum();
        }
        // Ensure contract remains not initialized; original requires !intitalized to allow SetMinSum.
        // Now deposit some Ether into c under this test contract so Acc[msg.sender].balance >= MinSum in original
        // Use Put to increase our account balance in c
        c.Put{value: sendAmount}(0);
        // Now call Collect which in original will only succeed if acc.balance>=MinSum and block.timestamp>unlockTime
        // We choose collectAmount <= sendAmount so call may succeed in original and transfer out funds; the mutant's inverted guard affects SetMinSum only,
        // but the distinguishing behavior reported was that MinSum changed after Collect in mutant. We assert MinSum unchanged.
        c.Collect(collectAmount);
        uint afterMin = c.MinSum();
        // General rule: if the contract was not initialized when MinSum was set (i.e., SetMinSum previously succeeded), then Collect must not change MinSum.
        assert(afterMin == beforeMin);
    }
    receive() external payable { }
}

