contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: actor address and amounts. We let the fuzzer find values that distinguish the mutant.
    function testFuzz_property(address actor, uint96 putAmount, uint96 collectAmount, uint32 lockDelta) public {
        vm.assume(actor != address(0));
        // keep values reasonable but wide
        uint256 putAmt = uint256(putAmount);
        uint256 collectAmt = uint256(collectAmount);
        uint256 lockTime = uint256(lockDelta);

        // 1) Ensure actor has funds and make a Put to set up their balance and unlockTime
        vm.deal(actor, putAmt + 1);
        vm.prank(actor);
        c.Put{value: putAmt}(lockTime);

        // 2) Do not call SetMinSum or Initialized here; the reference contract's SetMinSum only sets when intitalized==false
        // The mutant inverts the guard, making SetMinSum only set when intitalized==true. That inversion can cause
        // MinSum to be modified only in unexpected states. We want to ensure that Collect does not change MinSum in the reference.

        // Record MinSum before Collect
        uint256 beforeMin = c.MinSum();

        // 3) Warp time past unlock to allow Collect to proceed depending on inputs
        vm.warp(block.timestamp + lockTime + 1);

        // 4) Actor attempts to Collect collectAmt
        vm.prank(actor);
        // Collect is payable in the contract; call without sending extra value
        try c.Collect(collectAmt) {
            // success
        } catch {
            // ignore reverts; Collect may revert depending on inputs
        }

        // Exactly one assertion: in the correct contract, Collect never mutates MinSum, so it must remain equal to before
        assertTrue(c.MinSum() == beforeMin);
    }
}

