        Attacker attacker = new Attacker(c);

        // initialize contract: call SetLogFile and Initialized so intitalized can become true
        // SetLogFile expects an address; use attacker so attacker may be used as msg.sender in subsequent interactions
        c.SetLogFile(address(attacker));

        // Set MinSum while not initialized (this is allowed on reference: sets MinSum)
        c.SetMinSum(uint256(initialMin));

        // mark initialized
        c.Initialized();

        // Now change MinSum again to some other value to ensure different from potential mutation
        uint256 before = c.MinSum();

        // Fund the actor and have them Put some funds via attacker contract (attacker will forward with msg.sender = actor)
        vm.deal(address(attacker), putAmt);
        // attacker will perform a Put with provided lockTime and forward funds as itself (so Acc[attacker] accumulates)
        attacker.doPut{value: putAmt}(lockTime);

        // Now attempt to Collect from attacker: during Collect the c will call attacker (msg.sender.call)
        // The attacker fallback will try to call c.SetMinSum(...) reentrantly. On the reference, SetMinSum only sets when !intitalized, so since intitalized==true it will revert and not change MinSum. On the mutant, the guard is inverted and SetMinSum would succeed and change MinSum.
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: MinSum must remain equal to `before` after Collect on the reference for all admissible inputs.
        // This single assert reads c.MinSum() (public getter) and will hold on the correct contract for all inputs, while the mutant allows changing MinSum, causing this assertion to fail for some inputs.
        assertTrue(c.MinSum() == before);
    }
}

// Minimal adversarial helper: accepts funds in fallback and will call back into C.SetMinSum to try to change MinSum during Collect's external call
contract Attacker {
    C public target;
    constructor(C _t) {
        target = _t;
    }

    // helper to perform Put on target; called with value
    function doPut(uint lockTime) public payable {
        // call Put on target; forwarding calldata
        target.Put{value: msg.value}(lockTime);
    }

    // fallback: when target calls back during Collect, attempt to call SetMinSum to change MinSum
    fallback() external payable {
        // try to set MinSum to a nonzero value (e.g., block.timestamp) — this is the adversarial attempt
        // We don't catch revert here; if it reverts, the Collect may or may not revert depending on mutant/reference. That's acceptable.
        target.SetMinSum(block.timestamp);
    }
}

