        assert(firstReverted != secondReverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // require that this caller is an EOA-like caller not reentrant: no additional preconditions needed
        bool reverted;
        try c.Initialized() { reverted = false; } catch { reverted = true; }
        // Rule: When calling Initialized() from this caller on a contract that was not initialized yet,
        // the call must not revert. We express this by asserting reverted == false.
        // (This holds for the original which sets intitalized = true, but the mutant that does nothing
        // may revert due to e.g. a require checking intitalized elsewhere — capturing the difference.)
        assert(reverted == false);
    }
    receive() external payable { }
}

